from lib import *
S = SS('p59')
steps = [
    step("让 Chrome 打开一个会连 WebSocket 的页面(页面里 new WebSocket,连上后发 {\"op\":\"subscribe\"},之后只收消息),CDP 开着 Network:事件里有 Created 1 个、WillSendHandshakeRequest 1 个、HandshakeResponseReceived 1 个(状态 101)、FrameSent 1 个(就是那条订阅消息)、FrameReceived 19 个。1 秒内收到 19 帧,约每 53 ms 一帧,序号连续,页面 JS 数到的也是 19 条。服务器记录到浏览器的握手:Origin 是页面自己的地址 http://127.0.0.1:9960,Sec-WebSocket-Extensions 是 permessage-deflate; client_max_window_bits。", t=tl(S(1)), done=lidx(S(1), '事件种类与个数'), b=bars([['FrameReceived', 19, '19'], ['FrameSent', 1, '1'], ['握手响应', 1, '1']], 20, done=[0, 1, 2]), kv=KV([['握手状态', '101'], ['收到的帧', '19 个,序号连续'], ['页面发出的帧', '1 个订阅消息']], ['收到的帧'])),
    step("不用浏览器,用 websocket-client 1.9.0 直接连、发订阅、收 2 秒:收到 40 条(20 条/秒),序号 31…70,连续。服务器看到的握手:Origin 是 http://127.0.0.1:9970——不是我设的,是库自动补上的(服务器自己的地址);User-Agent 为空;没有 Sec-WebSocket-Extensions,也就是没有协商压缩。和浏览器那次对比:浏览器带自己页面的 Origin、带一长串 UA、请求了 permessage-deflate;这个库默认什么都不带。", t=tl(S(2)), done=lidx(S(2), '服务器记录的握手'), b=bars([['2 秒内收到', 40, '40'], ['序号范围', 40, '31…70']], 45, done=[0, 1]), kv=KV([['Origin', '库自动补成服务器自己的地址'], ['User-Agent', '空'], ['压缩扩展', '没有协商']], ['Origin'])),
    step("服务器每 1.5 秒主动断开一次(模拟重启),客户端跑 5 秒,三种写法:断了就不再连——收到 30 条,连接 1 次,序号没有缺口,但只拿到前 1.5 秒;断了等 0.3 秒重连并重新订阅(不带 since)——收到 86 条,连接 3 次,序号范围 98,中间丢了 12 条(断开期间服务器照常产生数据,新订阅从“现在”开始);重连并带上 since=最后收到的序号——收到 98 条,连接 3 次,缺口 0。注意:最后一种依赖服务器支持按序号回放,这个测试服务器的缓冲留着最近 2000 条;真实站点是否支持要看它的协议。", t=tl(S(3)), done=lidx(S(3), '重连并带上 since'), mark=lidx(S(3), '重新订阅(不带 since)'), b=bars([['不重连:收到', 30, '30'], ['重连不带 since:收到', 86, '86'], ['重连带 since:收到', 98, '98'], ['重连不带 since:丢失', 12, '12']], 100, done=[2], mark=[3]), kv=KV([['不重连', '30 条,1 次连接'], ['重连不带 since', '86 条,丢 12 条'], ['重连带 since', '98 条,缺口 0']], ['重连不带 since'])),
    step("心跳:这个服务器的规则是“1.0 秒内收不到客户端的任何消息,就发关闭帧,关闭码 4000”(规则是我定的,真实站点各有各的)。不发心跳:连接维持了 1.0 秒,收到 19 帧,客户端收到关闭码 4000,服务器记录由服务器关闭;每 0.4 秒发一个应用层 ping({\"op\":\"ping\"}):连接维持了 3.0 秒(测试到点),收到 66 帧,没有被关闭,服务器记录的是客户端关闭、码 1000。只会收消息的客户端并不“安静”——对服务器来说它什么都没发,会被当成死连接。", t=tl(S(4)), done=lidx(S(4), '不发心跳'), mark=lidx(S(4), '不发心跳'), b=bars([['不发心跳:连接秒数', 1.0, '1.0'], ['发心跳:连接秒数', 3.0, '3.0']], 3.2, mark=[0], done=[1]), kv=KV([['不发心跳', '1.0 秒后被关,码 4000'], ['每 0.4 秒 ping', '3.0 秒未被关闭'], ['这个规则', '是测试服务器自己定的']], ['不发心跳'])),
    step("握手校验:服务器只接受 Origin 为 http://shop.test 的握手,websocket-client 四种情况——默认(库补上 Origin: http://127.0.0.1:9970):403;suppress_origin=True 真的不带 Origin:403;带 http://evil.test:403;带 http://shop.test:握手成功。浏览器页面(Origin http://127.0.0.1:9960):服务器只允许页面自己的 Origin 时收到 16 条;服务器只允许 http://shop.test 时收到 0 条,Network 事件只有 Created、WillSendHandshakeRequest、FrameError、Closed 各 1 个。可见 Origin 只是请求里一个客户端自己填的头,非浏览器的客户端想填什么就填什么,所以它只能挡住别的网页的跨站连接,算不上认证。", t=tl(S(5)), done=lidx(S(5), 'websocket-client 带正确的 Origin'), mark=lidx(S(5), 'suppress_origin=True'), b=bars([['页面自己的 Origin:收到', 16, '16'], ['只允许 shop.test:收到', 0, '0']], 18, done=[0], mark=[1]), kv=KV([['库默认 Origin', '服务器自己的地址 → 403'], ['带正确的 Origin', '握手成功'], ['浏览器 + 不匹配', '0 条,FrameError + Closed']], ['带正确的 Origin'])),
]
A = mkartp('p59', 59, '爬虫,WebSocket,CDP,Network,重连,心跳,Origin,websocket-client,Python,真实验证,动画演示',
    '在本机的 WebSocket 服务器上实测:Chrome 的 CDP Network 事件里能看到握手、发出的帧和收到的帧;websocket-client 直接连时握手头和浏览器的差别;服务器断开后不重连、重连不带 since、重连带 since 分别丢多少数据;不发心跳会被服务器关闭;Origin 校验对库和浏览器各是什么结果。',
    '有些页面的数据不是 HTTP 响应,而是 WebSocket 推过来的。爬虫该怎么看这些帧、怎么直接连、断线后怎么不丢数据、为什么会被服务器断开?这篇用一个本机的 WebSocket 服务器逐个试。',
    [('19 帧 / 秒', 'Chrome 打开页面后 1 秒内,CDP 的 Network.webSocketFrameReceived 事件收到的帧数(序号连续)'), ('86 对 98 条', '服务器每 1.5 秒断开一次、客户端跑 5 秒:重连不带 since 只收到 86 条(丢 12 条),重连带 since 收到 98 条(缺口 0)'), ('1.0 对 3.0 秒', '服务器 1.0 秒收不到客户端消息就关闭:不发心跳连接只维持 1.0 秒,每 0.4 秒发一个 ping 则维持到 3.0 秒')],
    [('用浏览器看帧', '<p>CDP 开着 Network 时,页面里的 WebSocket 会产生 webSocketCreated、webSocketWillSendHandshakeRequest、webSocketHandshakeResponseReceived、webSocketFrameSent、webSocketFrameReceived 等事件,帧的内容在事件的 response.payloadData 里。不用解析页面就能拿到推送的数据;实验里 1 秒收到 19 帧,序号连续,和页面 JS 自己数到的一致。注意 CDP 的事件要持续读取,不读就收不到(我第一次写的脚本就是睡了 1 秒没读,只看到了 Created 一个事件)。</p>'),
     ('直接连', '<p>知道地址和订阅消息后可以不开浏览器,直接用客户端库连。浏览器的握手带 Origin(页面自己的地址)、长 User-Agent,并请求 permessage-deflate;websocket-client 默认的握手 Origin 是库自动补成服务器自己的地址、User-Agent 为空、不请求压缩。如果服务器对这些有要求,握手阶段就会有差别(见第五节)。</p>'),
     ('断线与重连', '<p>服务器重启或断开是常态。不重连就只拿到断开前的数据;重连后重新订阅,断开期间产生的数据会丢(实验里 5 秒丢了 12 条);带上最后收到的序号让服务器回放则没有缺口——前提是服务器支持。每条消息有序号时,客户端才能检查缺口;没有序号的数据流就没法知道丢了多少。</p>'),
     ('心跳', '<p>很多服务器会关闭长时间没收到消息的连接。只收不发的客户端对服务器来说是安静的:实验里服务器 1.0 秒收不到任何消息就关闭,不发心跳的客户端连接只维持了 1.0 秒;每 0.4 秒发一个应用层 ping 就一直保持。真实站点的心跳规则(协议层的 ping/pong 还是应用层的消息、间隔多久)要看它自己的实现,这里的规则是测试服务器定的。</p>'),
     ('握手里的 Origin', '<p>服务器可以在握手时检查 Origin。实验里服务器只允许一个 Origin 时,库默认补的 Origin、不带 Origin、错误的 Origin 都是 403,带对的才成功;浏览器页面的 Origin 不匹配时,页面收不到数据,CDP 里只看到 FrameError 和 Closed。因为非浏览器客户端可以随便填 Origin(这是从“带对的就成功”推出来的,没有拿别的服务器验证),Origin 校验只能防别的网页跨站连接,不是认证。</p>')],
    steps,
    [ENV_P + '。服务器是 aiohttp 写的本机 WebSocket 服务(每 50 ms 产生一条带递增序号的消息,订阅后推送,保留最近 2000 条用于回放;断开、心跳和 Origin 规则都是我在服务器上设定的);客户端是 websocket-client 1.9.0 和 Chrome 154(pcdp.py + CDP Network 事件);各情形跑一次,没有重复统计',
     '没有验证:真实站点的 WebSocket(协议各不相同:二进制帧、压缩、自定义心跳、签名的订阅消息);协议层 ping/pong(这里只测了应用层 ping);permessage-deflate 压缩帧的解码(浏览器协商了但库没协商,没有比较流量);wss://(TLS)下的行为;大量连接并发;断线重连的退避策略(第 30 篇讲的退避没有在这里测)'],
    'WebSocket 数据源')
